import type { Writeup } from "@/lib/types";

/** Fable-style narrative writeup: the case for each side, the call, and the
 *  honest caveat. Deterministic prose generated by the pipeline from the same
 *  numbers this page displays — never an independent opinion. Renders nothing
 *  until the prediction carries a writeup (pre-feature rows have none).
 *
 *  It lives inside the match page's single "Why" section, under that section's
 *  heading, so it carries no panel or eyebrow of its own. The two cases sit
 *  side by side from `sm` up (the for/against split the reasons list cannot
 *  make yet), then the call and the caveat. */
export function MatchWriteup({
  home,
  away,
  writeup,
}: {
  home: string;
  away: string;
  writeup: Writeup | null | undefined;
}) {
  if (!writeup) return null;
  const cases: Array<{ heading: string; body: string }> = [
    { heading: `The case for ${home}`, body: writeup.case_home },
    { heading: `The case for ${away}`, body: writeup.case_away },
  ];
  const verdict: Array<{ heading: string; body: string }> = [
    { heading: "The call", body: writeup.call },
    { heading: "The honest caveat", body: writeup.caveat },
  ];
  return (
    <div className="space-y-4">
      <div className="grid gap-4 sm:grid-cols-2">
        {cases.map((s) => (
          <Block key={s.heading} {...s} />
        ))}
      </div>
      {verdict.map((s) => (
        <Block key={s.heading} {...s} />
      ))}
    </div>
  );
}

function Block({ heading, body }: { heading: string; body: string }) {
  return (
    <div>
      <h3 className="mb-1 text-xs font-semibold uppercase tracking-wider text-muted">{heading}</h3>
      <p className="text-sm leading-relaxed text-foreground">{body}</p>
    </div>
  );
}
